#include <iostream>
#include <vector>
#include <set>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<string> S(N);
    for (auto&& s : S)
        cin >> s;

    // 連結した文字列の重複を取り除くために std::set を使う
    set<string> ans;
    for (const auto& s : S)
        for (const auto& t : S)
            if (s != t) // 異なる 2 つの文字列を
                ans.emplace(s + t); // 連結して追加

    // set の大きさが答え
    cout << size(ans) << endl;
    return 0;
}
